Properties.Octopus.Action.Script.ScriptBody:
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

Function GetLatestVersionOrSpecificVersionOfOctopusServer()
{
    if ([string]::IsNullOrEmpty($SpecificOctopusServerVersionToInstall))
    {
        Write-Host "No specific version has been selected, getting latest version from octopusdeploy.com"
        $versions = Invoke-WebRequest https://octopusdeploy.com/download/upgrade/v3 -UseBasicParsing | ConvertFrom-Json
        return $versions[-1].Version
    }
    Write-Host "Specific version has been selected"
    return $SpecificOctopusServerVersionToInstall
}
Function GetCurrentlyInstalledVersionOfOctopusServer()
{
    return (Get-Item "$InstallPath\Octopus.Server.exe").VersionInfo.FileVersion
}
Function NewOctopusTempFile()
{
    return [System.IO.Path]::GetTempFileName()
}
Function InvokeOctopusDownloadRequest($url, $method, $rangeStart, $rangeEnd)
{
    $request = [Net.HttpWebRequest]::Create($url)
    $request.Method = $method
    if ($method -eq "GET") { $request.AddRange([long]$rangeStart, [long]$rangeEnd) }
    return $request.GetResponse()
}

Function DownloadOctopusServer([string] $versionNumber, [long] $chunkSize = 32MB, [int] $maximumAttempts = 3)
{
    $url = "https://download.octopusdeploy.com/octopus/Octopus.$versionNumber-x64.msi"
    $tempFile = NewOctopusTempFile
    Write-Host "Downloading Octopus Server version $versionNumber"
    try
    {
        $response = InvokeOctopusDownloadRequest $url "HEAD" $null $null
        try { [long] $expectedLength = $response.ContentLength }
        finally { $response.Dispose() }
        if ($expectedLength -le 0) { throw "The download did not report a valid content length." }

        while ((Get-Item -LiteralPath $tempFile).Length -lt $expectedLength)
        {
            [long] $rangeStart = (Get-Item -LiteralPath $tempFile).Length
            [long] $rangeEnd = [Math]::Min($rangeStart + $chunkSize - 1, $expectedLength - 1)
            for ($attempt = 1; $attempt -le $maximumAttempts; $attempt++)
            {
                $response = $null
                $output = $null
                try
                {
                    $response = InvokeOctopusDownloadRequest $url "GET" $rangeStart $rangeEnd
                    $expectedRange = "bytes $rangeStart-$rangeEnd/$expectedLength"
                    if ($response.StatusCode -ne [Net.HttpStatusCode]::PartialContent -or
                        $response.Headers["Content-Range"] -ne $expectedRange)
                    {
                        throw "The server returned an invalid response for range $rangeStart-$rangeEnd."
                    }
                    $output = [IO.File]::Open($tempFile, "Append", "Write", "None")
                    $response.GetResponseStream().CopyTo($output)
                    $output.Dispose()
                    $output = $null
                    if ((Get-Item -LiteralPath $tempFile).Length -ne ($rangeEnd + 1))
                    {
                        throw "The downloaded range ended at an unexpected file length."
                    }
                    break
                }
                catch
                {
                    if ($attempt -eq $maximumAttempts) { throw }
                    Write-Warning "Range download failed; retrying from the last completed byte."
                    Start-Sleep -Seconds $attempt
                    $rangeStart = (Get-Item -LiteralPath $tempFile).Length
                }
                finally
                {
                    if ($output) { $output.Dispose() }
                    if ($response) { $response.Dispose() }
                }
            }
            $downloadedLength = (Get-Item -LiteralPath $tempFile).Length
            $percentComplete = [Math]::Round(($downloadedLength * 100) / $expectedLength, 2)
            Write-Host "Downloaded $downloadedLength of $expectedLength bytes ($percentComplete%)."
        }
        if ((Get-Item -LiteralPath $tempFile).Length -ne $expectedLength)
        {
            throw "The Octopus Server download has an unexpected file length."
        }
        if ((Get-AuthenticodeSignature -LiteralPath $tempFile).Status -ne "Valid")
        {
            throw "The Octopus Server installer does not have a valid Authenticode signature."
        }
    }
    catch
    {
        Remove-Item -LiteralPath $tempFile -Force -ErrorAction SilentlyContinue
        throw
    }
    Write-Host "Download completed"
    return $tempFile
}

Function StopOctopusServer()
{
    Write-Host "Stopping Server"
    . "$InstallPath\Octopus.Server.exe" service --stop --console --instance $InstanceName
}

Function InstallOctopusServer([string] $tempFile)
{
    Write-Host "Installing ..."
    $arguments = @("/i", "`"$tempFile`"", "/quiet", "/norestart")
    $installer = Start-Process "msiexec.exe" -ArgumentList $arguments -Wait -PassThru
    if ($installer.ExitCode -ne 0)
    {
        throw "Octopus Server installation failed with msiexec exit code $($installer.ExitCode)."
    }
}

Function RemoveTempFile([string] $temporaryFile)
{
    Write-Host "Deleting downloaded installer"
    Remove-Item -LiteralPath $temporaryFile -Force
}

Function StartOctopusServer()
{
    Write-Host "Starting Octopus Server"
    . "$InstallPath\Octopus.Server.exe" service --start --console --instance $InstanceName
}

Function InstallSetVersionOnOctopusServer([string] $currentlyInstalledVersion, [string] $selectedVersionToInstall)
{
    Write-Host "Currently installed version: $currentlyInstalledVersion"
    Write-Host "Selected version to install: $selectedVersionToInstall"
    $tempFile = DownloadOctopusServer $selectedVersionToInstall
    $serverStopped = $false
    $operationError = $null
    $recoveryError = $null
    try
    {
        StopOctopusServer
        $serverStopped = $true
        InstallOctopusServer $tempFile
    }
    catch { $operationError = $_ }
    finally
    {
        if ($serverStopped)
        {
            try { StartOctopusServer }
            catch
            {
                $recoveryError = $_
                Write-Warning "Failed to restart Octopus Server: $($_.Exception.Message)"
            }
        }
        RemoveTempFile $tempFile
    }
    if ($operationError) { throw $operationError }
    if ($recoveryError) { throw $recoveryError }
}

Function StartInstallationOfOctopusServer()
{
    $selectedVersionToInstall = GetLatestVersionOrSpecificVersionOfOctopusServer
    $currentlyInstalledVersion = GetCurrentlyInstalledVersionOfOctopusServer
    if ([version]$selectedVersionToInstall -eq [version]$currentlyInstalledVersion)
    {
        Write-Host "Octopus Server has already been installed with version $currentlyInstalledVersion"
    }
    else
    {
        InstallSetVersionOnOctopusServer $currentlyInstalledVersion $selectedVersionToInstall
    }
}

StartInstallationOfOctopusServer
